package configuration

import (
	"fmt"
	"strconv"
)

// Source resolves a configuration key to a raw value.
type Source func(key string) (value string, found bool)

type Config struct {
	Port  int
	Name  string
	Debug bool
}

func Load(source Source) (Config, error) {
	cfg := Config{
		Port:  8080,
		Name:  "helios",
		Debug: false,
	}

	if v, ok := source("HELIOS_PORT"); ok {
		n, err := strconv.Atoi(v)
		if err != nil {
			return Config{}, fmt.Errorf("helios port: %w", err)
		}
		if n < 1 || n > 65535 {
			return Config{}, fmt.Errorf("helios port: value %d out of range 1–65535", n)
		}
		cfg.Port = n
	}

	if v, ok := source("HELIOS_NAME"); ok {
		if v == "" {
			return Config{}, fmt.Errorf("helios name: must not be empty")
		}
		cfg.Name = v
	}

	if v, ok := source("HELIOS_DEBUG"); ok {
		b, err := strconv.ParseBool(v)
		if err != nil {
			return Config{}, fmt.Errorf("helios debug: %w", err)
		}
		cfg.Debug = b
	}

	return cfg, nil
}

package main

import (
	"fmt"
	"os"

	"example.helios/configuration"
)

func main() {
	source := func(key string) (string, bool) {
		v, ok := os.LookupEnv(key)
		return v, ok
	}

	cfg, err := configuration.Load(source)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("port=%d name=%s debug=%t\n", cfg.Port, cfg.Name, cfg.Debug)
}

package configuration

import (
	"errors"
	"strconv"
	"testing"
)

func env(m map[string]string) Source {
	return func(key string) (string, bool) {
		v, ok := m[key]
		return v, ok
	}
}

func TestDefaults(t *testing.T) {
	cfg, err := Load(env(nil))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "helios" {
		t.Errorf("Name = %q, want helios", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

func TestCustomValues(t *testing.T) {
	cfg, err := Load(env(map[string]string{
		"HELIOS_PORT":   "9090",
		"HELIOS_NAME":   "myapp",
		"HELIOS_DEBUG":  "true",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 9090 {
		t.Errorf("Port = %d, want 9090", cfg.Port)
	}
	if cfg.Name != "myapp" {
		t.Errorf("Name = %q, want myapp", cfg.Name)
	}
	if !cfg.Debug {
		t.Errorf("Debug = false, want true")
	}
}

func TestBadPort(t *testing.T) {
	_, err := Load(env(map[string]string{
		"HELIOS_PORT": "notanumber",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	if numErr := new(strconv.NumError); !errors.As(err, &numErr) {
		t.Errorf("error does not wrap *strconv.NumError: %v", err)
	}
}

func TestPortOutOfRange(t *testing.T) {
	_, err := Load(env(map[string]string{
		"HELIOS_PORT": "0",
	}))
	if err == nil {
		t.Fatal("expected error for port 0")
	}

	_, err = Load(env(map[string]string{
		"HELIOS_PORT": "65536",
	}))
	if err == nil {
		t.Fatal("expected error for port 65536")
	}

	// boundary: 1 and 65535 should work
	cfg, err := Load(env(map[string]string{
		"HELIOS_PORT": "1",
	}))
	if err != nil {
		t.Fatalf("unexpected error for port 1: %v", err)
	}
	if cfg.Port != 1 {
		t.Errorf("Port = %d, want 1", cfg.Port)
	}

	cfg, err = Load(env(map[string]string{
		"HELIOS_PORT": "65535",
	}))
	if err != nil {
		t.Fatalf("unexpected error for port 65535: %v", err)
	}
	if cfg.Port != 65535 {
		t.Errorf("Port = %d, want 65535", cfg.Port)
	}
}

func TestEmptyName(t *testing.T) {
	_, err := Load(env(map[string]string{
		"HELIOS_NAME": "",
	}))
	if err == nil {
		t.Fatal("expected error for empty name, got nil")
	}
}

func TestBadDebug(t *testing.T) {
	_, err := Load(env(map[string]string{
		"HELIOS_DEBUG": "yep",
	}))
	if err == nil {
		t.Fatal("expected error, got nil")
	}
	// ParseBool returns *strconv.ErrSyntax for bad values
	var syntaxErr *strconv.ErrSyntax
	if !errors.As(err, &syntaxErr) {
		t.Errorf("error does not wrap *strconv.ErrSyntax: %v", err)
	}
}

func TestDebugParseBoolVariants(t *testing.T) {
	tests := []struct {
		value string
		want  bool
	}{
		{"1", true},
		{"t", true},
		{"T", true},
		{"TRUE", true},
		{"true", true},
		{"True", true},
		{"0", false},
		{"f", false},
		{"F", false},
		{"FALSE", false},
		{"false", false},
		{"False", false},
	}
	for _, tc := range tests {
		cfg, err := Load(env(map[string]string{
			"HELIOS_DEBUG": tc.value,
		}))
		if err != nil {
			t.Errorf("HELIOS_DEBUG=%q: unexpected error: %v", tc.value, err)
			continue
		}
		if cfg.Debug != tc.want {
			t.Errorf("HELIOS_DEBUG=%q: Debug = %t, want %t", tc.value, cfg.Debug, tc.want)
		}
	}
}

func TestMissingKeysUseDefaults(t *testing.T) {
	// Only set some keys; others should use defaults
	cfg, err := Load(env(map[string]string{
		"HELIOS_NAME": "onlyname",
	}))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if cfg.Port != 8080 {
		t.Errorf("Port = %d, want 8080", cfg.Port)
	}
	if cfg.Name != "onlyname" {
		t.Errorf("Name = %q, want onlyname", cfg.Name)
	}
	if cfg.Debug {
		t.Errorf("Debug = true, want false")
	}
}

